import React, { useState, useEffect } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import Navbar from '../components/Navbar';
import Footer from '../components/Footer';

const PaymentPage = () => {
    const navigate = useNavigate();
    const location = useLocation();

    // Retrieve state passed from Shipping Step
    const { shippingInfo, cartItems, totals } = location.state || {};

    const [selectedMethod, setSelectedMethod] = useState('card');
    const [cardData, setCardData] = useState({ number: '', expiry: '', cvv: '' });
    const [errors, setErrors] = useState({});

    // Redirect if no state is present (e.g., direct navigation)
    useEffect(() => {
        if (!shippingInfo || !cartItems || !totals) {
            navigate('/checkout');
        }
    }, [shippingInfo, cartItems, totals, navigate]);

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setCardData(prev => ({ ...prev, [name]: value }));
        // Clear error when user starts typing
        if (errors[name]) setErrors(prev => ({ ...prev, [name]: null }));
    };

    const validateAndProceed = () => {
        if (selectedMethod === 'card') {
            const newErrors = {};
            if (!cardData.number) newErrors.number = true;
            if (!cardData.expiry) newErrors.expiry = true;
            if (!cardData.cvv) newErrors.cvv = true;

            if (Object.keys(newErrors).length > 0) {
                setErrors(newErrors);
                return; // Stop here
            }
        }

        // Pass all accumulated data to the Review Step
        navigate('/checkout/review', {
            state: {
                shippingInfo,
                cartItems,
                totals,
                paymentMethod: {
                    type: selectedMethod,
                    details: selectedMethod === 'card' ? { ...cardData, number: `xxxx xxxx xxxx ${cardData.number.slice(-4)}` } : {}
                }
            }
        });
    };

    if (!shippingInfo || !cartItems || !totals) {
        return null; // or a loading spinner
    }

    return (
        <div className="bg-background-light dark:bg-background-dark text-slate-900 dark:text-slate-100 font-display min-h-screen">
            <Navbar />

            <main className="max-w-7xl mx-auto px-6 py-12">
                {/* Progress Stepper */}
                <div className="mb-12 max-w-3xl">
                    <div className="flex items-center justify-between relative">
                        <div className="absolute top-1/2 left-0 w-full h-0.5 bg-primary/10 -z-10 -translate-y-1/2"></div>
                        {/* Step 1: Shipping (Completed) */}
                        <div className="flex flex-col items-center gap-2 bg-background-light dark:bg-background-dark pr-4 cursor-pointer" onClick={() => navigate('/checkout')}>
                            <div className="w-10 h-10 rounded-full bg-primary text-white flex items-center justify-center font-bold shadow-lg shadow-primary/20">
                                <i className="material-icons text-sm">check</i>
                            </div>
                            <span className="text-xs font-semibold uppercase tracking-widest text-primary">Shipping</span>
                        </div>
                        {/* Step 2: Payment (Active) */}
                        <div className="flex flex-col items-center gap-2 bg-background-light dark:bg-background-dark px-4">
                            <div className="w-10 h-10 rounded-full bg-primary text-white flex items-center justify-center font-bold shadow-lg shadow-primary/20">2</div>
                            <span className="text-xs font-semibold uppercase tracking-widest text-primary">Payment</span>
                        </div>
                        {/* Step 3: Review (Inactive) */}
                        <div className="flex flex-col items-center gap-2 bg-background-light dark:bg-background-dark pl-4">
                            <div className="w-10 h-10 rounded-full bg-white dark:bg-slate-800 border-2 border-primary/20 text-slate-400 flex items-center justify-center font-bold">3</div>
                            <span className="text-xs font-semibold uppercase tracking-widest text-slate-400">Review</span>
                        </div>
                    </div>
                </div>

                <div className="flex flex-col lg:flex-row gap-12">
                    {/* Left Column: Payment Methods */}
                    <div className="flex-1 space-y-8">
                        <div>
                            <h1 className="text-3xl dark:text-black font-bold mb-2">Payment Method</h1>
                            <p className="text-slate-500 dark:text-slate-400">All transactions are secure and encrypted.</p>
                        </div>
                        {/* Payment Options Accordion */}
                        <div className="space-y-4">
                            {/* Credit/Debit Card Option */}
                            <div className={`border rounded-lg overflow-hidden transition-all ${selectedMethod === 'card' ? 'border-primary ring-2 ring-primary bg-white dark:bg-slate-900/50' : 'border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900/50'}`}>
                                <label className="flex items-center justify-between p-6 cursor-pointer">
                                    <div className="flex items-center">
                                        <input
                                            type="radio"
                                            name="payment-method"
                                            checked={selectedMethod === 'card'}
                                            onChange={() => setSelectedMethod('card')}
                                            className="w-5 h-5 text-primary focus:ring-primary border-slate-300"
                                        />
                                        <span className="ml-4 light:bg-white font-semibold text-lg">Credit or Debit Card</span>
                                    </div>
                                    <div className="flex space-x-2">
                                        <img className="h-6 opacity-80" alt="Visa card logo" src="https://lh3.googleusercontent.com/aida-public/AB6AXuAjnOSQPYlUsaqDFCDDnp5Uu3c8G1LhFAL0wrrc1Kcdw07X5vW2L1lUJ7-hfg3g0FEPY9A4GMysl0Cpx_9rIDbM4F8DtgG3rQ8AvRm99ZpAcYj2Z--0CDQISPgkYVK_emovdMsqHu1zU5d25k9UySh4xurvPFqRQ4-WdCsw1RfKQCeV6lXQC0zKGkXQ0QVrqbSCXYGfEXLGQrj_O_TNppBVlgETjNCWTnYr5lucZxPIBVhVm79HLqmcfY2yh7KcZ87aQwE0TwvMYycz" />
                                        <img className="h-6 opacity-80" alt="Mastercard logo" src="https://lh3.googleusercontent.com/aida-public/AB6AXuAK97I12KxZD5iNjPDnYzTRtYlbAanFDMI6Vr75z64X4TZwELusnMGwnpV5Nideb40Yj-2aWV98jvUhIR5Zkw0731QRfErco6a-R4UceyNWW-FBuWxzzqbSNCboNlh4-Y3HEwXDomt0wXVSNbGx8lkNjMV07EmhfrQL2kMdE0xsweuc7sSsA33ynbMdVgu3LxCBwus8NzwILmRUwtLV5GD6sdWe7balems2KBe29pgNOdMTA5WlnOaQafQY8KZNrA3SpwIWjfhd9HNt" />
                                        <img className="h-6 opacity-80" alt="American Express logo" src="https://lh3.googleusercontent.com/aida-public/AB6AXuBcODZ17I-5fm9N6VUFaJOITzgR1tYhjJ4S9dctewlvnoCPXoJTXXwdPmaPGtF86wHx6qc1DGjwyeQOGzwM4HnB4JoXRYAi9PLdZZSA69tSA3yO2ui1E1Cc3nY3zK-jMSz2xDr1Ax-iP5aOHSN-IOVuXfN3EeX3aC_lSvCLh5BDTaaRsj7-8dNNVKA8myDRh62-PJOi-iIhVuUZNvfNMEE0wXIm_tIhYw3VkVa2I4nDeIWpgNOPrYerkvPMubX2eX7aat-xzAWzqFIR" />
                                    </div>
                                </label>

                                {selectedMethod === 'card' && (
                                    <div className="px-6 pb-8 space-y-6 animate-in fade-in slide-in-from-top-2 duration-300">
                                        <div className="grid grid-cols-1 gap-4">
                                            <div className="relative">
                                                <label className="block text-xs font-bold uppercase tracking-widest text-slate-500 mb-2">Card Number</label>
                                                <div className="relative">
                                                    <input
                                                        name="number"
                                                        value={cardData.number}
                                                        onChange={handleInputChange}
                                                        className={`w-full bg-background-light light:bg-slate-800 border-none rounded-lg p-4 focus:ring-2 focus:ring-primary ${errors.number ? 'ring-2 ring-red-500' : ''}`}
                                                        placeholder="0000 0000 0000 0000"
                                                        type="text"
                                                    />
                                                    <span className="absolute right-4 top-1/2 -translate-y-1/2 material-icons text-slate-400">credit_card</span>
                                                </div>
                                            </div>
                                        </div>
                                        <div className="grid grid-cols-2 gap-4">
                                            <div>
                                                <label className="block text-xs font-bold uppercase tracking-widest text-slate-500 mb-2">Expiration Date</label>
                                                <input
                                                    name="expiry"
                                                    value={cardData.expiry}
                                                    onChange={handleInputChange}
                                                    className={`w-full bg-background-light light:bg-slate-800 border-none rounded-lg p-4 focus:ring-2 focus:ring-primary ${errors.expiry ? 'ring-2 ring-red-500' : ''}`}
                                                    placeholder="MM / YY"
                                                    type="text"
                                                />
                                            </div>
                                            <div>
                                                <label className="block text-xs font-bold uppercase tracking-widest text-slate-500 mb-2">CVV</label>
                                                <div className="relative">
                                                    <input
                                                        name="cvv"
                                                        value={cardData.cvv}
                                                        onChange={handleInputChange}
                                                        className={`w-full bg-background-light light:bg-slate-800 border-none rounded-lg p-4 focus:ring-2 focus:ring-primary ${errors.cvv ? 'ring-2 ring-red-500' : ''}`}
                                                        placeholder="123"
                                                        type="password"
                                                    />
                                                    <span className="absolute right-4 top-1/2 -translate-y-1/2 material-icons text-slate-400 cursor-help" title="3-digit security code on the back of your card">help_outline</span>
                                                </div>
                                            </div>
                                        </div>
                                        <div className="flex items-center space-x-3 pt-2">
                                            <input className="rounded text-primary focus:ring-primary border-slate-300" id="save-card" type="checkbox" />
                                            <label className="text-sm text-slate-600 dark:text-slate-400" htmlFor="save-card">Save card details for future purchases</label>
                                        </div>
                                    </div>
                                )}
                            </div>

                            {/* PayPal Option */}
                            <div className={`border rounded-lg overflow-hidden transition-all ${selectedMethod === 'paypal' ? 'border-primary ring-2 ring-primary bg-white dark:bg-slate-900/50' : 'border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900/50'}`}>
                                <label className="flex items-center justify-between p-6 cursor-pointer">
                                    <div className="flex items-center">
                                        <input
                                            type="radio"
                                            name="payment-method"
                                            checked={selectedMethod === 'paypal'}
                                            onChange={() => setSelectedMethod('paypal')}
                                            className="w-5 h-5 text-primary focus:ring-primary border-slate-300"
                                        />
                                        <span className="ml-4 font-semibold text-lg">PayPal</span>
                                    </div>
                                    <img className="h-6" alt="PayPal official logo" src="https://lh3.googleusercontent.com/aida-public/AB6AXuCaQjTm2x7eLSj3HRpNObbrJhv7nyZPWcK7awD51qELsdshANwkftzi2CfJcy0lBfqwN0CYvgesfl_6ij7OKHfgVEoIcu-kmaFjex3kXoyZrwrmPmK-4poz2nIwCSNJOCk8b5c917Fdg1zBpvm_W8V7b9B4oWLTe4PVVUqTY4UE9jH_4CZZTsyA7YI7WybeOlo1iS964613RINlHfMxc37AiI7X5Fcfd7R2HIgLNv-mcVVGHbrjmvWPM082_bV57Tx5Ms60eTjtdAkg" />
                                </label>
                            </div>

                            {/* Apple Pay Option */}
                            <div className={`border rounded-lg overflow-hidden transition-all ${selectedMethod === 'applepay' ? 'border-primary ring-2 ring-primary bg-white dark:bg-slate-900/50' : 'border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900/50'}`}>
                                <label className="flex items-center justify-between p-6 cursor-pointer">
                                    <div className="flex items-center">
                                        <input
                                            type="radio"
                                            name="payment-method"
                                            checked={selectedMethod === 'applepay'}
                                            onChange={() => setSelectedMethod('applepay')}
                                            className="w-5 h-5 text-primary focus:ring-primary border-slate-300"
                                        />
                                        <span className="ml-4 font-semibold text-lg">Apple Pay</span>
                                    </div>
                                    <img className="h-6 dark:invert" alt="Apple Pay logo" src="https://lh3.googleusercontent.com/aida-public/AB6AXuCfTbW00f71wk8Mu7p_dMnJ3RzE9dwMIJQw2BoGtULSbO63Q0an0F_65kOHUAbZHsbvPHv4uGDrNNffm6RTQpeJ36XFLGQmwNgnvlb4xNFddIAwWEQVKn0o4L3Ee_Hy4XEPEbm6dXZSip-ADi9-HorOm3wg-LcSwmyq7eV357a0aFfHPiwtUaSn9m73jAxpOv8GcHxFkZF7OCqvMAKeeCMWVEdczk2dqKvei52q685QVu193t7i781XO-YIKEBdSbxiuCR0twWXqQBX" />
                                </label>
                            </div>
                        </div>

                        {/* Billing Address Section */}
                        <div className="pt-8 border-t border-slate-200 dark:border-slate-800">
                            <h2 className="text-xl dark:text-black font-bold mb-4">Billing Address</h2>
                            <div className="bg-white dark:bg-slate-900/50 border border-slate-200 dark:border-slate-800 rounded-lg p-6">
                                <div className="flex items-start space-x-4">
                                    <div className="flex items-center h-5">
                                        <input defaultChecked className="w-5 h-5 rounded text-primary focus:ring-primary border-slate-300" id="billing-same" type="checkbox" />
                                    </div>
                                    <label className="flex flex-col cursor-pointer" htmlFor="billing-same">
                                        <span className="font-semibold">Same as shipping address</span>
                                        <span className="text-sm text-slate-500 mt-1">
                                            {shippingInfo.firstName} {shippingInfo.lastName}<br />
                                            {shippingInfo.address}<br />
                                            {shippingInfo.city}, {shippingInfo.postalCode}, {shippingInfo.country}
                                        </span>
                                    </label>
                                </div>
                            </div>
                        </div>

                        {/* Verification Badges */}
                        <div className="flex items-center justify-center space-x-8 pt-4">
                            <div className="flex items-center text-slate-400 grayscale opacity-70">
                                <span className="material-icons text-xl mr-2">verified_user</span>
                                <span className="text-[10px] font-bold uppercase tracking-widest">Norton Secured</span>
                            </div>
                            <div className="flex items-center text-slate-400 grayscale opacity-70">
                                <span className="material-icons text-xl mr-2">security</span>
                                <span className="text-[10px] font-bold uppercase tracking-widest">PCI Compliance</span>
                            </div>
                            <div className="flex items-center text-slate-400 grayscale opacity-70">
                                <span className="material-icons text-xl mr-2">lock</span>
                                <span className="text-[10px] font-bold uppercase tracking-widest">SSL Encrypted</span>
                            </div>
                        </div>
                    </div>

                    {/* Right Column: Order Summary (Sticky) */}
                    <aside className="w-full lg:w-[400px]">
                        <div className="sticky top-28 bg-white light:bg-white p-8 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm">
                            <h3 className="text-lg dark:text-black font-bold mb-6 flex items-center justify-between">
                                Order Summary
                                <span className="bg-primary/10 text-primary text-xs px-2 py-1 rounded-full">{cartItems.length} Items</span>
                            </h3>
                            {/* Line Items */}
                            <div className="space-y-6 mb-8 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar">
                                {cartItems.map((item, index) => (
                                    <div key={index} className="flex space-x-4">
                                        <div className="w-20 h-24 bg-background-light dark:bg-slate-800 rounded overflow-hidden flex-shrink-0">
                                            <img className="w-full h-full object-cover" alt={item.name} src={item.image} />
                                        </div>
                                        <div className="flex-1 flex flex-col justify-between py-1">
                                            <div>
                                                <h4 className="text-sm dark:text-black font-semibold uppercase leading-tight">{item.name}</h4>
                                                <p className="text-xs text-slate-500 mt-1">Size: {item.size} | Qty: {item.quantity}</p>
                                            </div>
                                            <div className="text-sm dark:text-black font-bold">₹{(item.price * item.quantity).toLocaleString()}</div>
                                        </div>
                                    </div>
                                ))}
                            </div>

                            {/* Promo Code */}
                            <div className="mb-8">
                                <div className="flex space-x-2">
                                    <input className="flex-1 bg-background-light dark:text-black light:bg-slate-800 border-none rounded-lg px-4 py-3 text-sm focus:ring-1 focus:ring-primary" placeholder="Promo Code" type="text" />
                                    <button className="px-4 py-2 dark:text-black border border-slate-200 dark:border-slate-700 rounded-lg text-xs font-bold uppercase tracking-widest hover:bg-slate-50 dark:hover:bg-slate-800 dark:hover:text-white transition-colors">Apply</button>
                                </div>
                            </div>

                            {/* Price Breakdown */}
                            <div className="space-y-3 border-t border-slate-100 dark:border-slate-800 pt-6 mb-8">
                                <div className="flex justify-between text-sm text-slate-500">
                                    <span>Subtotal</span>
                                    <span>₹{totals.subtotal.toLocaleString()}</span>
                                </div>
                                <div className="flex justify-between text-sm text-slate-500">
                                    <span>Shipping</span>
                                    <span className="text-primary font-medium">Free</span>
                                </div>
                                <div className="flex justify-between text-sm text-slate-500">
                                    <span>Estimated Tax</span>
                                    <span>₹{totals.tax.toLocaleString()}</span>
                                </div>
                                <div className="flex justify-between text-xl font-bold pt-4 text-slate-900 dark:text-white border-t border-slate-100 dark:border-slate-800 mt-4">
                                    <span>Total</span>
                                    <span>₹{totals.total.toLocaleString()}</span>
                                </div>
                            </div>

                            <button
                                onClick={validateAndProceed}
                                className="w-full bg-primary hover:bg-primary/90 text-white font-bold py-5 rounded-lg uppercase tracking-[0.2em] text-sm transition-all shadow-lg shadow-primary/20 flex items-center justify-center space-x-2"
                            >
                                <span>Review Order</span>
                                <span className="material-icons text-sm">arrow_forward</span>
                            </button>

                            {Object.keys(errors).length > 0 && (
                                <p className="mt-4 text-center text-red-500 text-xs font-bold animate-bounce">
                                    Please complete the payment details.
                                </p>
                            )}

                            <p className="text-[10px] text-center text-slate-400 mt-6 leading-relaxed uppercase tracking-wider">
                                By placing your order, you agree to our <br />
                                <a href="#" className="underline hover:text-primary">Terms of Service</a> and <a href="#" className="underline hover:text-primary">Privacy Policy</a>
                            </p>
                        </div>
                    </aside>
                </div>
            </main>

            {/* Footer */}
            <Footer />
        </div>
    );
};

export default PaymentPage;
